def check(command, allow, jail="/work"):
    """Return None if `command` may run, else a refusal string that starts with 'blocked:'."""
    stripped = command.strip()
    if not stripped:
        return "blocked: empty command"
    prog = stripped.split()[0]
    if prog not in allow:
        return f"blocked: '{prog}' is not on the allow-list"
