import re
from pathlib import PurePosixPath

SHELL_CONTROL = re.compile(r"[;&|<>`\n]|\$\(")


def _within(token, jail):
    t, j = PurePosixPath(token), PurePosixPath(jail)
    return t == j or j in t.parents


def check(command, allow, jail="/work"):
    """Return None if `command` may run, else a refusal string that starts with 'blocked:'."""
    stripped = command.strip()
    if not stripped:
        return "blocked: empty command"
    found = SHELL_CONTROL.search(stripped)          # before the allow-list: these smuggle a second program
    if found:
        return f"blocked: shell control character {found.group(0)!r} is refused"
    prog = stripped.split()[0]
    if prog not in allow:
        return f"blocked: '{prog}' is not on the allow-list"
    if ".." in command:
        return "blocked: path traversal"
    for token in stripped.split():
        if token.startswith("/") and not _within(token, jail):   # path components, not a string prefix
            return f"blocked: '{token}' is outside the jail"
    return None
